# Starting pictures for the Contact page, from the images committed in images/.
PICTURES = {
    "info_image": ("media/m1.jpeg", "Artistic impression of a welcoming reception lounge at an M3M development"),
    "faq_image": ("media/m9.jpeg", "Artistic impression of landscaped gardens at an M3M development"),
}


def add_pictures(apps, schema_editor):
    page = apps.get_model("core", "InnerPage").objects.filter(key="contact").first()
    if page is None:
        return
    for field, (source, alt) in PICTURES.items():
        if getattr(page, field):
            continue
        name = f"page-banners/contact-{Path(source).name}"
        if not default_storage.exists(name):
            with open(Path(settings.BASE_DIR) / "images" / source, "rb") as image:
                name = default_storage.save(name, File(image))
        setattr(page, field, name)
        setattr(page, f"{field}_alt", alt)
    page.save()


